properties.query:
// This is a combination of 3 queries designed to detect suspicious activity in Windows Credential Manager
// This is a method to bypass authentication on windows 
let parent_processes = dynamic(["cmd.exe","powershell.exe"]);
let cmd_all = dynamic(["rundll32","keymgr.dll","KRShowKeyMgr"]);
let query1 = 
_Im_ProcessCreate(commandline_has_all=cmd_all,parentprocess_has_any=parent_processes,targetprocess_has_any="rundll32.exe");
let parent_processes2 = dynamic(["rundll.exe"]);
let cmd_all2 = dynamic(["credwiz.exe","B"]);
let query2 = 
_Im_ProcessCreate(commandline_has_all=cmd_all2,parentprocess_has_any=parent_processes2,targetprocess_has_any="credwiz.exe");
let cmd_all3 = dynamic(["vaultcmd /listcreds","Windows Credentials"]);
let query3 =
_Im_ProcessCreate(commandline_has_all=cmd_all3);
union isfuzzy=true
query1,query2,query3
| extend
    Account = tostring(column_ifexists("ActorUsername", "")),
    AccountDomain = tostring(column_ifexists("ActorUserDomain", "")),
    Computer = tostring(column_ifexists("DvcHostname", "")),
    ProcessName = tostring(column_ifexists("TargetProcessName", "")),
    ProcessId = tostring(column_ifexists("TargetProcessId", "")),
    CommandLine = tostring(column_ifexists("CommandLine", ""))
| where isnotempty(ProcessName)
